// Intake in one step: keep only PDF attachments, drop ones already turned into a Bill,
// and build the Gemini request. An email with no PDF emits nothing, which ends the run here.
const GEMINI_MODEL = 'gemini-3.5-flash';

const SYSTEM_PROMPT = [
  'You extract structured data from vendor invoices (bills the user RECEIVES and must pay).',
  'The document may be a text PDF or a scanned/image-only PDF; read it visually if needed.',
  'Return STRICT JSON only, matching the response schema. No markdown, no commentary.',
  'Rules:',
  '- vendor_name is the party ISSUING the invoice (the supplier), not the customer being billed.',
  '- Use null for any field that is not printed on the invoice. NEVER guess or invent dates, amounts, emails or numbers.',
  '- Dates must be YYYY-MM-DD. If a date is ambiguous or absent, use null.',
  '- Amounts are plain numbers: no currency symbols or thousands separators.',
  '- One line_items entry per invoiced line. If there is no quantity column, use quantity 1.',
  '- subtotal is the pre-tax total, tax_amount the total tax, total_payable the final amount due.',
  '- payment_method is as stated on the invoice (e.g. "COD", "Bank transfer"), else null.',
].join('\n');

const nullable = (type) => ({ type, nullable: true });

const RESPONSE_SCHEMA = {
  type: 'OBJECT',
  properties: {
    vendor_name: nullable('STRING'),
    vendor_email: nullable('STRING'),
    invoice_number: nullable('STRING'),
    invoice_date: nullable('STRING'),
    due_date: nullable('STRING'),
    line_items: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          description: { type: 'STRING' },
          quantity: { type: 'NUMBER' },
          unit_price: { type: 'NUMBER' },
          total: { type: 'NUMBER' },
        },
        required: ['description', 'quantity', 'unit_price', 'total'],
      },
    },
    subtotal: nullable('NUMBER'),
    tax_amount: nullable('NUMBER'),
    total_payable: nullable('NUMBER'),
    payment_method: nullable('STRING'),
  },
  required: ['vendor_name', 'invoice_number', 'line_items', 'total_payable'],
};

// Dedupe layer 1: workflow static data persists across production runs (not manual test runs).
// Layer 2 is the "Check Existing Bill" lookup against Xero itself.
const store = $getWorkflowStaticData('global');
store.processed = store.processed || {};
const seen = new Set();

const isPdf = (b) => b.mimeType === 'application/pdf' || /\.pdf$/i.test(b.fileName || '');

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;

  // Gmail items carry an `id`; items from the optional test Form Trigger do not.
  const isManual = !j.id;
  const messageId = isManual ? 'manual' : j.id;

  const internalMs = Number(j.internalDate);
  let received = internalMs ? new Date(internalMs) : new Date(j.date || Date.now());
  if (isNaN(received.getTime())) received = new Date();

  for (const [prop, bin] of Object.entries(items[i].binary || {})) {
    if (!isPdf(bin)) continue;

    const attachmentName = bin.fileName || 'invoice.pdf';
    // One key per attachment so an email with two invoices yields two bills.
    const dedupeKey = `${messageId}:${attachmentName}`;
    if (store.processed[dedupeKey] || seen.has(dedupeKey)) continue;
    seen.add(dedupeKey);

    const buffer = await this.helpers.getBinaryDataBuffer(i, prop);

    out.push({
      json: {
        messageId,
        attachmentName,
        dedupeKey,
        subject: j.subject || (isManual ? 'Manual upload' : '(no subject)'),
        fromAddress: (j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || '',
        receivedDate: received.toISOString().slice(0, 10),
        geminiModel: GEMINI_MODEL,
        geminiBody: {
          systemInstruction: { parts: [{ text: SYSTEM_PROMPT }] },
          contents: [
            {
              role: 'user',
              parts: [
                { inlineData: { mimeType: bin.mimeType || 'application/pdf', data: buffer.toString('base64') } },
                { text: 'Extract the invoice data as JSON.' },
              ],
            },
          ],
          generationConfig: {
            temperature: 0,
            responseMimeType: 'application/json',
            responseSchema: RESPONSE_SCHEMA,
          },
        },
      },
    });
  }
}

return out;

// Parse the Gemini response, validate it (plan step 4) and work out fallback dates.
const TOLERANCE = 1.0;
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

const toNum = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = typeof v === 'number' ? v : Number(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};

const toStr = (v) => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  return s === '' ? null : s;
};

const validDate = (v) => {
  const s = toStr(v);
  if (!s || !ISO_DATE.test(s)) return null;
  const d = new Date(`${s}T00:00:00Z`);
  return !isNaN(d.getTime()) && d.toISOString().slice(0, 10) === s ? s : null;
};

// Models occasionally wrap JSON in fences despite instructions: strip them defensively.
const parseModelJson = (text) => {
  const t = String(text).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try {
    return JSON.parse(t);
  } catch (err) {
    const start = t.indexOf('{');
    const end = t.lastIndexOf('}');
    if (start >= 0 && end > start) return JSON.parse(t.slice(start, end + 1));
    throw err;
  }
};

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const resp = items[i].json;
  const { geminiBody, ...meta } = $('Prepare Invoices').itemMatching(i).json;

  const notes = [];
  const fallbacks = [];
  let extracted = null;
  let rawText = '';

  const candidate = resp.candidates && resp.candidates[0];
  rawText = ((candidate && candidate.content && candidate.content.parts) || [])
    .filter((p) => p.text && !p.thought)
    .map((p) => p.text)
    .join('');

  if (resp.promptFeedback && resp.promptFeedback.blockReason) {
    notes.push(`Gemini blocked the request: ${resp.promptFeedback.blockReason}`);
  }
  if (candidate && candidate.finishReason && !['STOP', undefined].includes(candidate.finishReason)) {
    notes.push(`Gemini finishReason was ${candidate.finishReason} (output may be truncated)`);
  }

  if (!rawText) {
    notes.push('Gemini returned no text');
  } else {
    try {
      const p = parseModelJson(rawText);
      extracted = {
        vendor_name: toStr(p.vendor_name),
        vendor_email: toStr(p.vendor_email),
        invoice_number: toStr(p.invoice_number),
        invoice_date: toStr(p.invoice_date),
        due_date: toStr(p.due_date),
        line_items: Array.isArray(p.line_items)
          ? p.line_items.map((li) => ({
              description: toStr(li.description),
              quantity: toNum(li.quantity),
              unit_price: toNum(li.unit_price),
              total: toNum(li.total),
            }))
          : [],
        subtotal: toNum(p.subtotal),
        tax_amount: toNum(p.tax_amount),
        total_payable: toNum(p.total_payable),
        payment_method: toStr(p.payment_method),
      };
    } catch (err) {
      notes.push(`AI response was not valid JSON: ${err.message}`);
    }
  }

  let billDate = null;
  let billDueDate = null;

  if (extracted) {
    if (!extracted.vendor_name) notes.push('vendor_name is missing');
    if (!extracted.invoice_number) notes.push('invoice_number is missing');
    if (extracted.total_payable === null) notes.push('total_payable is missing or not a number');
    if (extracted.line_items.length === 0) {
      notes.push('line_items is empty');
    }
    extracted.line_items.forEach((li, n) => {
      if (li.quantity === null || li.unit_price === null) {
        notes.push(`line_items[${n}] ("${li.description || ''}") is missing quantity or unit_price`);
      }
    });

    const { subtotal, tax_amount, total_payable } = extracted;
    if (subtotal !== null && tax_amount !== null && total_payable !== null) {
      const diff = Math.abs(subtotal + tax_amount - total_payable);
      if (diff > TOLERANCE) {
        notes.push(
          `subtotal (${subtotal}) + tax (${tax_amount}) = ${(subtotal + tax_amount).toFixed(2)} ` +
            `does not match total_payable (${total_payable}); difference ${diff.toFixed(2)}`
        );
      }
    }

    // Fallback dates: invoice date -> email received date; due date -> invoice date (e.g. COD).
    const invDate = validDate(extracted.invoice_date);
    if (extracted.invoice_date && !invDate) {
      fallbacks.push(`invoice_date "${extracted.invoice_date}" was not a valid YYYY-MM-DD date`);
    }
    billDate = invDate || meta.receivedDate;
    if (!invDate) {
      fallbacks.push(`Invoice date not on invoice: used the email received date (${billDate})`);
    }

    const dueDate = validDate(extracted.due_date);
    if (extracted.due_date && !dueDate) {
      fallbacks.push(`due_date "${extracted.due_date}" was not a valid YYYY-MM-DD date`);
    }
    billDueDate = dueDate || billDate;
    if (!dueDate) {
      const cod = /\b(cod|cash on delivery)\b/i.test(extracted.payment_method || '');
      fallbacks.push(
        `Due date not on invoice: set to the bill date (${billDueDate})${cod ? ' - payment method is COD' : ''}`
      );
    }
  }

  out.push({
    json: {
      ...meta,
      extracted,
      raw_text: rawText,
      billDate,
      billDueDate,
      fallbacks,
      valid: notes.length === 0,
      validation_notes: notes,
      outcome: notes.length === 0 ? 'valid' : 'invalid',
    },
  });
}

return out;

// Plan step 6: use the first connected Xero organisation (known limitation: no disambiguation).
// Also prepares the contact search so the HTTP node only has to send it.
const connections = $input.all().map((i) => i.json).filter((c) => c && c.tenantId);
if (connections.length === 0) {
  throw new Error('Xero /connections returned no organisations for this credential');
}
const tenantId = connections[0].tenantId;
const tenantName = connections[0].tenantName || '';
const otherOrgs = connections.slice(1).map((c) => c.tenantName || c.tenantId);

// Xero "where" strings have no escape mechanism worth relying on: drop quotes/backslashes.
const clean = (s) => String(s).replace(/["\\]/g, '').trim();

return $('Parse & Validate')
  .all()
  .filter((i) => i.json.valid)
  .map((i) => {
    const { vendor_name, vendor_email } = i.json.extracted;
    // Email match first; the name clause also catches an existing contact with no email on file,
    // which matters because Xero rejects creating a second contact with the same name.
    const contactWhere = vendor_email
      ? `EmailAddress=="${clean(vendor_email)}" OR Name.Contains("${clean(vendor_name)}")`
      : `Name.Contains("${clean(vendor_name)}")`;
    return { json: { ...i.json, tenantId, tenantName, otherOrgs, contactWhere } };
  });

// Plan step 7: choose the best existing Contact, or prepare the body to create one.
const lc = (s) => String(s || '').trim().toLowerCase();

return $input.all().map((it, i) => {
  const base = $('Resolve Tenant').itemMatching(i).json;
  const contacts = it.json.Contacts || [];
  const { vendor_name, vendor_email } = base.extracted;

  let match = null;
  let contactMatch = null;

  if (vendor_email) {
    match = contacts.find((c) => lc(c.EmailAddress) === lc(vendor_email));
    if (match) contactMatch = 'email';
  }
  if (!match) {
    match = contacts.find((c) => lc(c.Name) === lc(vendor_name));
    if (match) contactMatch = 'name (exact)';
  }
  if (!match && contacts.length > 0) {
    match = contacts[0];
    contactMatch = 'name (partial)';
  }

  const newContact = { Name: vendor_name };
  if (vendor_email) newContact.EmailAddress = vendor_email;

  // Dedupe layer 2 lookup: does this vendor already have a bill with this invoice number?
  // (A contact we are about to create cannot have one, so that path skips the lookup.)
  const clean = (s) => String(s).replace(/["\\]/g, '');
  const billWhere = match
    ? `Type=="ACCPAY" AND Contact.ContactID==Guid("${match.ContactID}") ` +
      `AND InvoiceNumber=="${clean(base.extracted.invoice_number)}"`
    : null;

  return {
    json: {
      ...base,
      contactFound: Boolean(match),
      contactId: match ? match.ContactID : null,
      contactName: match ? match.Name : vendor_name,
      contactMatch,
      billWhere,
      newContactBody: { Contacts: [newContact] },
    },
  };
});

// Runs after either contact path:
//  - contact found   -> input is the "Check Existing Bill" response ({ Invoices })
//  - contact created -> input is the "Create Contact" response ({ Contacts })
// Skips the bill if Xero already has it, otherwise builds the payload (plan step 8).
const BILL_STATUS = 'DRAFT'; // hard requirement: never AUTHORISED

// Your Xero organisation's purchase tax type code (e.g. "INPUT"; codes vary per org and country).
// When set, each line carries this TaxType plus its share of the invoice's tax_amount so the draft's
// total matches the invoice. Empty = send no tax info (Xero may then show the pre-tax total).
// To find the code: open an existing bill with tax in Xero's API Explorer / GET Invoices and read
// LineItems[].TaxType.
const TAX_TYPE = 'INPUT';

const round2 = (n) => Math.round(n * 100) / 100;

// Split the invoice's tax across lines in proportion to line amounts; the last line absorbs rounding.
const allocateTax = (lines, tax) => {
  const amounts = lines.map((li) => li.quantity * li.unit_price);
  const base = amounts.reduce((a, b) => a + b, 0);
  if (!(base > 0)) return null;
  let allocated = 0;
  return amounts.map((amt, n) => {
    const share = n === amounts.length - 1 ? round2(tax - allocated) : round2((tax * amt) / base);
    allocated += share;
    return share;
  });
};

return $input.all().map((it, i) => {
  const base = $('Pick Contact').itemMatching(i).json;
  let { contactId, contactName, contactMatch } = base;

  if (it.json.Contacts) {
    const contact = it.json.Contacts[0];
    if (!contact || !contact.ContactID) {
      throw new Error(`Xero did not return a ContactID when creating "${base.extracted.vendor_name}"`);
    }
    contactId = contact.ContactID;
    contactName = contact.Name;
    contactMatch = 'created new contact';
  } else {
    const existing = (it.json.Invoices || []).filter(
      (inv) => !['VOIDED', 'DELETED'].includes(inv.Status)
    );
    if (existing.length > 0) {
      const inv = existing[0];
      return {
        json: {
          ...base,
          duplicate: true,
          outcome: 'duplicate',
          existingBill: { id: inv.InvoiceID, number: inv.InvoiceNumber, status: inv.Status },
        },
      };
    }
  }

  const { extracted } = base;
  const tax = extracted.tax_amount;
  const taxShares = TAX_TYPE && typeof tax === 'number' && tax > 0 ? allocateTax(extracted.line_items, tax) : null;

  const bill = {
    Type: 'ACCPAY',
    Contact: { ContactID: contactId },
    Date: base.billDate,
    DueDate: base.billDueDate,
    InvoiceNumber: extracted.invoice_number,
    Reference: extracted.invoice_number,
    // No AccountCode, Total or SubTotal: not needed for a draft; Xero computes totals itself.
    LineItems: extracted.line_items.map((li, n) => ({
      Description: li.description || 'Invoice line',
      Quantity: li.quantity,
      UnitAmount: li.unit_price,
      ...(taxShares ? { TaxType: TAX_TYPE, TaxAmount: taxShares[n] } : {}),
    })),
    ...(taxShares ? { LineAmountTypes: 'Exclusive' } : {}),
    Status: BILL_STATUS,
  };

  if (bill.Status !== 'DRAFT' || bill.Type !== 'ACCPAY') {
    throw new Error('Refusing to build a bill that is not an ACCPAY DRAFT');
  }

  return {
    json: {
      ...base,
      contactId,
      contactName,
      contactMatch,
      duplicate: false,
      billBody: { Invoices: [bill] },
    },
  };
});

// One composer for every outcome. Inputs (each is a different shape):
//  - Create Bill response   ({ Invoices })              -> success (also records the dedupe key)
//  - Duplicate? true        (outcome: 'duplicate')      -> skipped
//  - Valid? false           (outcome: 'invalid')        -> needs manual review
//  - On Workflow Error      ({ execution, workflow })   -> failure
const esc = (v) =>
  String(v === null || v === undefined ? '' : v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
const money = (v) => (typeof v === 'number' ? v.toFixed(2) : '-');
const list = (arr) => `<ul>${arr.map((x) => `<li>${esc(x)}</li>`).join('')}</ul>`;
const pre = (s) =>
  `<pre style="background:#f4f4f4;padding:8px;white-space:pre-wrap">${esc(s)}</pre>`;

const source = (j) =>
  `<p><b>Email:</b> ${esc(j.subject)}<br><b>From:</b> ${esc(j.fromAddress)}<br>` +
  `<b>Attachment:</b> ${esc(j.attachmentName)}</p>`;

const lineTable = (lines) =>
  '<table border="1" cellpadding="4" cellspacing="0" style="border-collapse:collapse">' +
  '<tr><th>Description</th><th>Qty</th><th>Unit</th><th>Total</th></tr>' +
  lines
    .map(
      (l) =>
        `<tr><td>${esc(l.description)}</td><td>${esc(l.quantity)}</td>` +
        `<td>${money(l.unit_price)}</td><td>${money(l.total)}</td></tr>`
    )
    .join('') +
  '</table>';

// Find the Build Bill item that produced this Xero bill. Matching on invoice number + contact
// (not item position) stays correct when Build Bill ran more than once in a batch.
const findBuildBillItem = (inv) => {
  for (let run = 0; run < 5; run++) {
    let items;
    try {
      items = $('Build Bill').all(0, run);
    } catch (e) {
      break;
    }
    const hit = items.find((b) => {
      const sent = b.json.billBody && b.json.billBody.Invoices[0];
      return sent && sent.InvoiceNumber === inv.InvoiceNumber && sent.Contact.ContactID === (inv.Contact && inv.Contact.ContactID);
    });
    if (hit) return hit.json;
  }
  return null;
};

const store = $getWorkflowStaticData('global');
store.processed = store.processed || {};

const success = (inv) => {
  const j = findBuildBillItem(inv);
  if (j) {
    store.processed[j.dedupeKey] = { xeroInvoiceId: inv.InvoiceID, at: new Date().toISOString() };
  }
  // If the context can't be matched the bill still exists; report from Xero's own response.
  const e = j
    ? j.extracted
    : {
        vendor_name: inv.Contact && inv.Contact.Name,
        invoice_number: inv.InvoiceNumber,
        total_payable: null,
        line_items: (inv.LineItems || []).map((l) => ({
          description: l.Description,
          quantity: l.Quantity,
          unit_price: l.UnitAmount,
          total: l.LineAmount,
        })),
      };
  const url = `https://go.xero.com/AccountsPayable/View.aspx?InvoiceID=${inv.InvoiceID}`;
  const mismatch =
    typeof inv.Total === 'number' && typeof e.total_payable === 'number' && Math.abs(inv.Total - e.total_payable) > 0.01;

  let html = `<h3>Draft bill created</h3>${j ? source(j) : ''}`;
  if (j) {
    html +=
      `<p><b>Vendor:</b> ${esc(e.vendor_name)} (${esc(j.contactMatch)}` +
      `${j.contactMatch === 'name (partial)' ? ` - matched to existing contact "${esc(j.contactName)}", please check it is the right vendor` : ''})<br>`;
  } else {
    html += `<p><b>Vendor:</b> ${esc(e.vendor_name)}<br>`;
  }
  html +=
    `<b>Invoice #:</b> ${esc(e.invoice_number)}<br>` +
    `<b>Bill date:</b> ${esc(j ? j.billDate : inv.DateString)} &nbsp; <b>Due:</b> ${esc(j ? j.billDueDate : inv.DueDateString)}<br>` +
    `<b>Xero status:</b> ${esc(inv.Status)} &nbsp; <a href="${esc(url)}">Open in Xero</a></p>` +
    lineTable(e.line_items) +
    `<p><b>Invoice total:</b> ${money(e.total_payable)} &nbsp; <b>Xero total:</b> ${money(inv.Total)} ` +
    `(tax in Xero: ${money(inv.TotalTax)})</p>`;
  if (mismatch) {
    html +=
      `<p style="color:#b00020"><b>Xero's total differs from the invoice total.</b> ` +
      `No tax type is sent unless TAX_TYPE is set in the Build Bill node, so Xero may not have applied ` +
      `the invoice's tax. Review the draft before approving.</p>`;
  }
  if (inv.Status !== 'DRAFT') {
    html += `<p style="color:#b00020"><b>WARNING: Xero reports status ${esc(inv.Status)}, expected DRAFT.</b></p>`;
  }
  if (j && j.fallbacks.length) html += `<p><b>Defaults applied:</b></p>${list(j.fallbacks)}`;
  if (j && j.otherOrgs && j.otherOrgs.length) {
    html += `<p><i>Multiple Xero organisations are connected; used "${esc(j.tenantName)}" (first). Others: ${esc(j.otherOrgs.join(', '))}</i></p>`;
  }
  return { subject: `Draft bill created in Xero: ${e.vendor_name} #${e.invoice_number}`, html };
};

const failure = (j) => {
  const ex = j.execution || {};
  const err = ex.error || {};
  return {
    subject: `Invoice automation FAILED at "${ex.lastNodeExecuted || 'unknown node'}"`,
    html:
      `<h3>Invoice automation failed</h3>` +
      `<p><b>Workflow:</b> ${esc(j.workflow && j.workflow.name)}<br>` +
      `<b>Failed node:</b> ${esc(ex.lastNodeExecuted)}<br>` +
      `<b>Execution:</b> ${ex.url ? `<a href="${esc(ex.url)}">${esc(ex.id)}</a>` : esc(ex.id)}</p>` +
      pre(err.message || JSON.stringify(err, null, 2)) +
      `<p>The invoice was not marked as processed. Fix the cause, then use <b>Retry</b> on that execution ` +
      `in n8n. Nothing is duplicated: an existing Xero bill is detected before a new one is created.</p>`,
  };
};

return $input.all().map((item) => {
  const j = item.json;
  let msg;

  if (j.execution && j.workflow) {
    msg = failure(j);
  } else if (j.Invoices) {
    msg = success(j.Invoices[0]);
  } else if (j.outcome === 'duplicate') {
    msg = {
      subject: `Skipped: bill already exists in Xero (#${j.extracted.invoice_number})`,
      html:
        `<h3>No bill created: duplicate</h3>${source(j)}` +
        `<p>Xero already has a bill for ${esc(j.extracted.vendor_name)} with invoice number ` +
        `${esc(j.extracted.invoice_number)} (status ${esc(j.existingBill.status)}).</p>`,
    };
  } else {
    msg = {
      subject: `Invoice needs manual review: ${j.extracted && j.extracted.vendor_name ? j.extracted.vendor_name : j.subject}`,
      html:
        `<h3>Invoice needs manual review</h3>${source(j)}` +
        `<p>Nothing was created in Xero. Issues found:</p>${list(j.validation_notes)}` +
        `<p><b>Extracted data:</b></p>${pre(j.extracted ? JSON.stringify(j.extracted, null, 2) : j.raw_text || '(nothing extracted)')}`,
    };
  }

  return { json: msg };
});
